Deterministic, single-threaded (no timing/concurrency needed) — add to crates/interaction-adapter-declarative/tests/aip_link.rs:

#[tokio::test]
async fn a_second_supersede_before_drain_loses_the_first_drop() {
    let raw = MockRawLink::with_caps("esp32-01", None, vec!["led.set".into(), FRAG_CAP.into()], Some(639));
    let link = DeviceLink::new(raw.clone(), "esp32-01".into(), None);
    link.ensure_ready().await.expect("handshake");

    let start_xfer = |xfer: u32, total: u16| DeviceMsg::AipFrag {
        xfer, seq: 0, total, bytes: 4, crc: "00000000".into(), data: "{".into(),
    };

    // xfer=1 starts (buffered, not yet complete).
    assert_eq!(link.admit_aip(&start_xfer(1, 2)), Some(AipAdmission::FragmentBuffered));
    // xfer=2 supersedes xfer=1 -> xfer=1's drop goes into the single pending slot,
    // NOT drained yet (no expire_fragments() call in between, mirroring the
    // real gap between the write inside admit_aip and the run() loop's later
    // expire_fragments() call at declarative_session.rs:425).
    assert_eq!(link.admit_aip(&start_xfer(2, 2)), Some(AipAdmission::FragmentBuffered));
    // xfer=3 supersedes xfer=2 -> overwrites the still-undrained slot.
    assert_eq!(link.admit_aip(&start_xfer(3, 2)), Some(AipAdmission::FragmentBuffered));

    // Only xfer=2's drop is ever recoverable; xfer=1's drop is gone forever.
    let drop = link.expire_fragments().expect("a drop must be reported");
    assert_eq!(drop.xfer, 2, "xfer=1's drop was silently lost");
    assert!(link.expire_fragments().is_none());
}

This currently fails (or would report xfer==2 while asserting xfer==1's loss is the defect) against the present protocol.rs, proving the single-slot overwrite. Fix direction: replace the `Option<FragmentDrop>` slot with a small bounded queue (e.g. `VecDeque<FragmentDrop>` capped at 2, matching "at most one old + one in-flight" transfers per device) drained FIFO by `expire_fragments()`, or have each of the discard call sites (`cancel_reassembly`, the superseded path) push-and-immediately-audit inline instead of relying on a shared slot the run() loop must later collect.

